/* From Uiverse.io by ForzDz - Tags: switch, starrating, 3d cool effect */
.__UIV_SCOPE__ .rating {
  display: inline-block;
  opacity: 1;
}

.__UIV_SCOPE__ .rating input {
  display: none;
  opacity: 1;
}

.__UIV_SCOPE__ .rating label {
  float: right;
  cursor: pointer;
  color: #ccc;
  transition: color 0.3s, transform 0.3s, box-shadow 0.3s;
}

.__UIV_SCOPE__ .rating label:before {
  content: '\2605';
  font-size: 30px;
  transition: color 0.3s;
}

.__UIV_SCOPE__ .rating input:checked ~ label,
.__UIV_SCOPE__ .rating label:hover,
.__UIV_SCOPE__ .rating label:hover ~ label {
  color: #ffc300;
  transform: scale(1.2);
  transition: color 0.3s, transform 0.3s, box-shadow 0.3s;
  animation: bounce 0.5s ease-in-out alternate;
}

@keyframes bounce {
  to {
    transform: scale(1.3);
  }
}
